/** @module cli/completions/fish */

export function generateFish() {
  return `# fish completion for rule-mcp
# Generated by rule-mcp completions
# Install: rule-mcp completions --shell fish > ~/.config/fish/completions/rule-mcp.fish

complete -c rule-mcp -f

# Commands
complete -c rule-mcp -n "__fish_use_subcommand" -a serve     -d "Start MCP server"
complete -c rule-mcp -n "__fish_use_subcommand" -a daemon    -d "Manage background daemon"
complete -c rule-mcp -n "__fish_use_subcommand" -a install   -d "Install into agent/IDE"
complete -c rule-mcp -n "__fish_use_subcommand" -a uninstall -d "Remove from agent/IDE"
complete -c rule-mcp -n "__fish_use_subcommand" -a config    -d "Print mcp.json snippet"
complete -c rule-mcp -n "__fish_use_subcommand" -a tools     -d "List or call MCP tools"
complete -c rule-mcp -n "__fish_use_subcommand" -a doctor    -d "System health check"
complete -c rule-mcp -n "__fish_use_subcommand" -a skills    -d "Manage skills"
complete -c rule-mcp -n "__fish_use_subcommand" -a adr       -d "Architecture Decision Records"
complete -c rule-mcp -n "__fish_use_subcommand" -a handoff   -d "LLM context handoff"
complete -c rule-mcp -n "__fish_use_subcommand" -a completions -d "Generate shell completion"
complete -c rule-mcp -n "__fish_use_subcommand" -a help      -d "Show help"

# Daemon actions
complete -c rule-mcp -n "__fish_seen_subcommand_from daemon" -a "start stop status logs" -f

# Tools subcommands
complete -c rule-mcp -n "__fish_seen_subcommand_from tools" -a "list call" -f

# Skills actions
complete -c rule-mcp -n "__fish_seen_subcommand_from skills" -a "reload" -f

# ADR actions
complete -c rule-mcp -n "__fish_seen_subcommand_from adr" -a "new" -f

# Global options
complete -c rule-mcp -l help -s h -d "Show help"
complete -c rule-mcp -l transport -x -a "stdio sse" -d "Transport type"
complete -c rule-mcp -l agent -x -a "claude codex cursor copilot gemini cline roo zed opencode antigravity devin kilo kimi vibe grok droid kiro qwen pi vscode jetbrains neovim emacs" -d "Agent name"
complete -c rule-mcp -l format -x -a "full brief minimal" -d "Handoff format"
complete -c rule-mcp -l status -x -a "proposed accepted deprecated superseded" -d "ADR status"
complete -c rule-mcp -l shell -x -a "zsh bash fish" -d "Shell type"
complete -c rule-mcp -l global -d "Use global install"
complete -c rule-mcp -l dry-run -d "Preview without applying"
complete -c rule-mcp -l force -d "Override existing config"
complete -c rule-mcp -l compress -d "Compress handoff output"
complete -c rule-mcp -l telemetry -d "Include telemetry"
`;
}
